<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Balloon Pop Archery</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Press+Start+2P&family=VT323&display=swap" rel="stylesheet">
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html, body { width: 100%; height: 100%; overflow: hidden; background: #1a1a2e; }
  body { font-family: 'VT323', monospace; }
  #wrap { position: relative; width: 100vw; height: 100vh; }
  canvas { display: block; width: 100%; height: 100%; cursor: crosshair; image-rendering: pixelated; }
  .overlay {
    position: absolute; inset: 0; display: flex; flex-direction: column;
    align-items: center; justify-content: center; gap: 24px;
    background: rgba(10, 10, 30, 0.82); z-index: 10;
  }
  .hidden { display: none; }
  h1 {
    font-family: 'Press Start 2P', monospace; font-size: clamp(20px, 5vw, 44px);
    color: #ffd93d; text-shadow: 4px 4px 0 #c0392b, 8px 8px 0 rgba(0,0,0,.4);
    text-align: center; line-height: 1.4;
  }
  .sub { font-size: clamp(18px, 3vw, 28px); color: #a8d8ff; text-align: center; line-height: 1.5; }
  .btn {
    font-family: 'Press Start 2P', monospace; font-size: clamp(12px, 2vw, 18px);
    padding: 16px 32px; color: #fff; background: #e74c3c; border: 4px solid #fff;
    box-shadow: 0 6px 0 #922b21; cursor: pointer; transition: transform .08s, box-shadow .08s;
  }
  .btn:hover { background: #ff6b5b; }
  .btn:active { transform: translateY(6px); box-shadow: 0 0 0 #922b21; }
  .score-big { font-family: 'Press Start 2P', monospace; font-size: clamp(24px, 6vw, 56px); color: #7bed9f; text-shadow: 3px 3px 0 #145a32; }
  .hud {
    position: absolute; top: 12px; left: 0; right: 0; display: flex;
    justify-content: space-between; padding: 0 20px; z-index: 5; pointer-events: none;
  }
  .hud span {
    font-family: 'Press Start 2P', monospace; font-size: clamp(10px, 1.6vw, 16px);
    color: #fff; text-shadow: 2px 2px 0 rgba(0,0,0,.6);
  }
  #timer { color: #ffd93d; }
</style>
</head>
<body>
<div id="wrap">
  <canvas id="cv"></canvas>
  <div class="hud hidden" id="hud">
    <span id="score">SCORE 0</span>
    <span id="timer">60</span>
    <span id="lives">&#127938;&#127938;&#127938;</span>
  </div>
  <div class="overlay" id="startScreen">
    <h1>BALLOON POP<br>ARCHERY</h1>
    <div class="sub">Aim with the mouse &middot; hold to draw the bow &middot; release to fire<br>Pop balloons before time runs out &middot; 3 misses and you lose</div>
    <button class="btn" id="startBtn">START</button>
  </div>
  <div class="overlay hidden" id="endScreen">
    <h1 id="endTitle">TIME UP!</h1>
    <div class="score-big" id="finalScore">0</div>
    <div class="sub" id="endMsg"></div>
    <button class="btn" id="retryBtn">PLAY AGAIN</button>
  </div>
</div>
